(3026790, 426615, 39239, '<td valign="top">Great portrait, with great post.  Love the lighting. strobes?</td>', 'Great portrait, with great post.  Love the lighting. strobes?', '2006-11-13 13:07:43.000000', NULL, 1),
(3026791, 426680, 46177, '<td valign="top">Nice angle and great contrast, the very white seagull sets the whole thing off very well.</td>', 'Nice angle and great contrast, the very white seagull sets the whole thing off very well.', '2006-11-13 13:07:48.000000', NULL, 1),
(3026796, 425965, 46177, '<td valign="top">Cute pose and nice tones, works well with the white background.</td>', 'Cute pose and nice tones, works well with the white background.', '2006-11-13 13:08:17.000000', NULL, 1),
(3026810, 425820, 46177, '<td valign="top">Love the soft feel you have created with this, soft but detailed at the same time.  Very nice, great contrast here as well.</td>', 'Love the soft feel you have created with this, soft but detailed at the same time.  Very nice, great contrast here as well.', '2006-11-13 13:12:55.000000', NULL, 1),
