(3027174, 426455, 58330, '<td valign="top">I like the tranquility.7</td>', 'I like the tranquility.7', '2006-11-13 14:37:15.000000', NULL, 1),
(3027182, 425926, 65319, '<td valign="top">Wonderful capture of the amazing clouds.  The composition is well done with the black at the bottom moving the eye upwards into the grays and the white of the sky.  8.</td>', 'Wonderful capture of the amazing clouds.  The composition is well done with the black at the bottom moving the eye upwards into the grays and the white of the sky.  8.', '2006-11-13 14:38:44.000000', NULL, 1),
